```vue client/src/components/teams/TeamChannelsIconView.vue
<script setup>
import ChatIcon from '@/components/chat/ChatIcon.vue'
</script>

<template>
  <div class="flex flex-col w-full gap-3 items-center">
    <div v-if="allChannels.length > 0" class="text-[9px] font-extrabold tracking-wider text-base-content/40 uppercase mb-1 text-center">
      Channels
    </div>

    <!-- Channel icons -->
    <div class="flex flex-col gap-2 w-full items-center">
      <div
        v-for="channel in allChannels"
        :key="channel.id"
        @click="openChannel(channel)"
        class="relative cursor-pointer transition-all duration-200 group"
        :title="channel.name"
      >
        <div
          class="w-10 h-10 rounded-lg flex items-center justify-center text-xs font-bold border transition-all duration-200"
          :class="isActiveChannel(channel)
            ? 'bg-primary text-primary-content border-primary/60 shadow-md ring-2 ring-primary/20'
            : 'bg-base-300 text-base-content border-base-content/10 hover:bg-base-300/80 hover:border-base-content/20'"
        >
          <ChatIcon :mode="channel.mode" class="text-xs" />
        </div>

        <!-- Unread badge -->
        <div v-if="channel.unread > 0" class="absolute -top-1 -right-1 w-5 h-5 rounded-full bg-error text-white text-[9px] font-bold flex items-center justify-center border border-base-100">
          {{ channel.unread > 9 ? '9+' : channel.unread }}
        </div>

        <!-- Tooltip on hover -->
        <div class="absolute left-14 top-1/2 -translate-y-1/2 bg-base-300 text-base-content text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none whitespace-nowrap z-50 border border-base-content/10">
          {{ channel.name }}
        </div>

        <!-- Settings button on hover -->
        <button
          class="absolute -bottom-2 -right-2 btn btn-xs btn-circle btn-ghost p-0 w-5 h-5 min-h-0 opacity-0 group-hover:opacity-100 transition-opacity duration-200"
          @click.stop="$emit('edit-channel', { channel })"
          title="Edit channel"
        >
          <i class="fa-solid fa-gear text-[9px]"></i>
        </button>
      </div>

      <!-- Show more indicator if channels exceed limit -->
      <div v-if="allChannels.length > 5" class="text-[9px] text-base-content/40 mt-2">
        +{{ allChannels.length - 5 }}
      </div>
    </div>

    <!-- Category management button -->
    <div class="divider my-1 w-6"></div>
    <button
      class="btn btn-xs btn-ghost p-1 w-6 h-6 min-h-0 text-base-content/50 hover:text-base-content"
      @click="showCategoryMenu"
      title="Category menu"
    >
      <i class="fa-solid fa-folder text-xs"></i>
    </button>
  </div>
</template>

<script>
export default {
  name: 'TeamChannelsIconView',
  props: {
    activeTeam: {
      type: Object,
      default: null
    }
  },
  computed: {
    allChannels() {
      if (!this.activeTeam) return []
      const channels = []
      const categories = this.activeTeam.categories || []

      // Flatten all channels from all categories
      categories.forEach(category => {
        if (category.channels) {
          channels.push(...category.channels)
        }
      })

      // Return top 5 channels or all if less than 5
      return channels.slice(0, 5)
    }
  },
  methods: {
    isActiveChannel(channel) {
      return this.$storex?.ui?.activeTeamChannel?.id === channel.id
    },
    openChannel(channel) {
      // Find the category that contains this channel
      const categories = this.activeTeam.categories || []
      let parentCategory = null

      for (const category of categories) {
        if (category.channels && category.channels.some(c => c.id === channel.id)) {
          parentCategory = category
          break
        }
      }

      if (parentCategory) {
        this.$storex.teams.markChannelRead({ teamId: this.activeTeam.id, channelId: channel.id })
        this.$storex.ui.openTeamChannel({ team: this.activeTeam, channel })
      }
    },
    showCategoryMenu() {
      // Emit event to show category management modal/dropdown
      this.$emit('edit-category', { showAll: true })
    }
  }
}
</script>
